public static void main(String pArgs[]) {
        // Defaults
        int argIdx = 0;
        int speedTest = -1;
        boolean overWrite = false;
        boolean monochrome = false;
        boolean gray = false;
        int numColors = 256;
        String dither = null;
        String quality = null;
        String format = null;
        Color background = null;
        boolean transparency = false;
        String paletteFileName = null;
        boolean errArgs = false;

        // Parse args
        while ((argIdx < pArgs.length) && (pArgs[argIdx].charAt(0) == '-') && (pArgs[argIdx].length() >= 2)) {
            if ((pArgs[argIdx].charAt(1) == 's') || pArgs[argIdx].equals("--speedtest")) {
                argIdx++;

                // Get number of iterations
                if ((pArgs.length > argIdx) && (pArgs[argIdx].charAt(0) != '-')) {
                    try {
                        speedTest = Integer.parseInt(pArgs[argIdx++]);
                    }
                    catch (NumberFormatException nfe) {
                        errArgs = true;
                        break;
                    }
                }
                else {

                    // Default to 10 iterations
                    speedTest = 10;
                }
            }
            else if ((pArgs[argIdx].charAt(1) == 'w') || pArgs[argIdx].equals("--overwrite")) {
                overWrite = true;
                argIdx++;
            }
            else if ((pArgs[argIdx].charAt(1) == 'c') || pArgs[argIdx].equals("--colors")) {
                argIdx++;

                try {
                    numColors = Integer.parseInt(pArgs[argIdx++]);
                }
                catch (NumberFormatException nfe) {
                    errArgs = true;
                    break;
                }
            }
            else if ((pArgs[argIdx].charAt(1) == 'g') || pArgs[argIdx].equals("--grayscale")) {
                argIdx++;
                gray = true;
            }
            else if ((pArgs[argIdx].charAt(1) == 'm') || pArgs[argIdx].equals("--monochrome")) {
                argIdx++;
                numColors = 2;
                monochrome = true;
            }
            else if ((pArgs[argIdx].charAt(1) == 'd') || pArgs[argIdx].equals("--dither")) {
                argIdx++;
                dither = pArgs[argIdx++];
            }
            else if ((pArgs[argIdx].charAt(1) == 'p') || pArgs[argIdx].equals("--palette")) {
                argIdx++;
                paletteFileName = pArgs[argIdx++];
            }
            else if ((pArgs[argIdx].charAt(1) == 'q') || pArgs[argIdx].equals("--quality")) {
                argIdx++;
                quality = pArgs[argIdx++];
            }
            else if ((pArgs[argIdx].charAt(1) == 'b') || pArgs[argIdx].equals("--bgcolor")) {
                argIdx++;
                try {
                    background = StringUtil.toColor(pArgs[argIdx++]);
                }
                catch (Exception e) {
                    errArgs = true;
                    break;
                }
            }
            else if ((pArgs[argIdx].charAt(1) == 't') || pArgs[argIdx].equals("--transparency")) {
                argIdx++;
                transparency = true;
            }
            else if ((pArgs[argIdx].charAt(1) == 'f') || pArgs[argIdx].equals("--outputformat")) {
                argIdx++;
                format = StringUtil.toLowerCase(pArgs[argIdx++]);
            }
            else if ((pArgs[argIdx].charAt(1) == 'h') || pArgs[argIdx].equals("--help")) {
                argIdx++;

                // Setting errArgs to true, to print usage
                errArgs = true;
            }
            else {
                System.err.println("Unknown option \"" + pArgs[argIdx++] + "\"");
            }
        }
        if (errArgs || (pArgs.length < (argIdx + 1))) {
            System.err.println("Usage: IndexImage [--help|-h] [--speedtest|-s <integer>] [--bgcolor|-b <color>] [--colors|-c <integer> | --grayscale|g | --monochrome|-m | --palette|-p <file>] [--dither|-d (default|diffusion|none)] [--quality|-q (default|high|low)] [--transparency|-t] [--outputformat|-f (gif|jpeg|png|wbmp|...)] [--overwrite|-w] <input> [<output>]");
            System.err.print("Input format names: ");
            String[] readers = ImageIO.getReaderFormatNames();

            for (int i = 0; i < readers.length; i++) {
                System.err.print(readers[i] + ((i + 1 < readers.length)
                        ? ", "
                        : "\n"));
            }

            System.err.print("Output format names: ");
            String[] writers = ImageIO.getWriterFormatNames();

            for (int i = 0; i < writers.length; i++) {
                System.err.print(writers[i] + ((i + 1 < writers.length)
                        ? ", "
                        : "\n"));
            }
            System.exit(5);
        }

        // Read in image
        File in = new File(pArgs[argIdx++]);

        if (!in.exists()) {
            System.err.println("File \"" + in.getAbsolutePath() + "\" does not exist!");
            System.exit(5);
        }

        // Read palette if needed
        File paletteFile = null;

        if (paletteFileName != null) {
            paletteFile = new File(paletteFileName);
            if (!paletteFile.exists()) {
                System.err.println("File \"" + in.getAbsolutePath() + "\" does not exist!");
                System.exit(5);
            }
        }

        // Make sure we can write
        File out;

        if (argIdx < pArgs.length) {
            out = new File(pArgs[argIdx/*++*/]);

            // Get format from file extension
            if (format == null) {
                format = FileUtil.getExtension(out);
            }
        }
        else {
            // Create new file in current dir, same name + format extension
            String baseName = FileUtil.getBasename(in);

            // Use png as default format
            if (format == null) {
                format = "png";
            }
            out = new File(baseName + '.' + format);
        }

        if (!overWrite && out.exists()) {
            System.err.println("The file \"" + out.getAbsolutePath() + "\" allready exists!");
            System.exit(5);
        }

        // Do the image processing
        BufferedImage image = null;
        BufferedImage paletteImg = null;

        try {
            image = ImageIO.read(in);
            if (image == null) {
                System.err.println("No reader for image: \"" + in.getAbsolutePath() + "\"!");
                System.exit(5);
            }
            if (paletteFile != null) {
                paletteImg = ImageIO.read(paletteFile);
                if (paletteImg == null) {
                    System.err.println("No reader for image: \"" + paletteFile.getAbsolutePath() + "\"!");
                    System.exit(5);
                }
            }
        }
        catch (IOException ioe) {
            ioe.printStackTrace(System.err);
            System.exit(5);
        }

        // Create hints
        int hints = DITHER_DEFAULT;

        if ("DIFFUSION".equalsIgnoreCase(dither)) {
            hints |= DITHER_DIFFUSION;
        }
        else if ("DIFFUSION_ALTSCANS".equalsIgnoreCase(dither)) {
            hints |= DITHER_DIFFUSION_ALTSCANS;
        }
        else if ("NONE".equalsIgnoreCase(dither)) {
            hints |= DITHER_NONE;
        }
        else {

            // Don't care, use default
        }
        if ("HIGH".equalsIgnoreCase(quality)) {
            hints |= COLOR_SELECTION_QUALITY;
        }
        else if ("LOW".equalsIgnoreCase(quality)) {
            hints |= COLOR_SELECTION_FAST;
        }
        else {

            // Don't care, use default
        }
        if (transparency) {
            hints |= TRANSPARENCY_BITMASK;
        }

        //////////////////////////////
        // Apply bg-color WORKAROUND!
        // This needs to be done BEFORE palette creation to have desired effect..
        if ((background != null) && (paletteImg == null)) {
            paletteImg = createSolid(image, background);
        }

        ///////////////////////////////
        // Index
        long start = 0;

        if (speedTest > 0) {
            // SPEED TESTING
            System.out.println("Measuring speed!");
            start = System.currentTimeMillis();
            // END SPEED TESTING
        }

        BufferedImage indexed;
        IndexColorModel colors;

        if (monochrome) {
            indexed = getIndexedImage(image, MonochromeColorModel.getInstance(), background, hints);
            colors = MonochromeColorModel.getInstance();
        }
        else if (gray) {
            //indexed = ImageUtil.toBuffered(ImageUtil.grayscale(image), BufferedImage.TYPE_BYTE_GRAY);
            image = ImageUtil.toBuffered(ImageUtil.grayscale(image));
            indexed = getIndexedImage(image, colors = getIndexColorModel(image, numColors, hints), background, hints);

            // In casse of speedtest, this makes sense...
            if (speedTest > 0) {
                colors = getIndexColorModel(indexed, numColors, hints);
            }
        }
        else if (paletteImg != null) {
            // Get palette from image
            indexed = getIndexedImage(ImageUtil.toBuffered(image, BufferedImage.TYPE_INT_ARGB),
                                      colors = getIndexColorModel(paletteImg, numColors, hints), background, hints);
        }
        else {
            image = ImageUtil.toBuffered(image, BufferedImage.TYPE_INT_ARGB);
            indexed = getIndexedImage(image, colors = getIndexColorModel(image, numColors, hints), background, hints);
        }

        if (speedTest > 0) {
            // SPEED TESTING
            System.out.println("Color selection + dither: " + (System.currentTimeMillis() - start) + " ms");
            // END SPEED TESTING
        }

        // Write output (in given format)
        try {
            if (!ImageIO.write(indexed, format, out)) {
                System.err.println("No writer for format: \"" + format + "\"!");
            }
        }
        catch (IOException ioe) {
            ioe.printStackTrace(System.err);
        }

        if (speedTest > 0) {
            // SPEED TESTING
            System.out.println("Measuring speed!");

            // Warmup!
            for (int i = 0; i < 10; i++) {
                getIndexedImage(image, colors, background, hints);
            }

            // Measure
            long time = 0;

            for (int i = 0; i < speedTest; i++) {
                start = System.currentTimeMillis();
                getIndexedImage(image, colors, background, hints);
                time += (System.currentTimeMillis() - start);
                System.out.print('.');
                if ((i + 1) % 10 == 0) {
                    System.out.println("\nAverage (after " + (i + 1) + " iterations): " + (time / (i + 1)) + "ms");
                }
            }

            System.out.println("\nDither only:");
            System.out.println("Total time (" + speedTest + " invocations): " + time + "ms");
            System.out.println("Average: " + time / speedTest + "ms");
            // END SPEED TESTING
        }
    }

@Override
    public BufferedImage read(int imageIndex, ImageReadParam param) throws IOException {
        checkBounds(imageIndex);

        // Delegate reading for JPEG/PNG compression
        if (header.getCompression() == DIB.COMPRESSION_JPEG || header.getCompression() == DIB.COMPRESSION_PNG) {
            return readUsingDelegate(header.getCompression(), param);
        }

        int width = getWidth(imageIndex);
        int height = getHeight(imageIndex);

        ImageTypeSpecifier rawType = getRawImageType(imageIndex);
        validateSourceSize(rawType, width, height, imageInput.length(), MAX_EXPANSION_RATIO);
        BufferedImage destination = getDestination(param, getImageTypes(imageIndex), width, height);

        ColorModel colorModel = destination.getColorModel();
        if (colorModel instanceof IndexColorModel && ((IndexColorModel) colorModel).getMapSize() < header.getColorsUsed()) {
            processWarningOccurred(
                    String.format("Color map contains more colors than raster allows (%d). Ignoring entries above %d.",
                            header.getColorsUsed(), ((IndexColorModel) colorModel).getMapSize())
            );
        }

        // BMP rows are padded to 4 byte boundary
        int rowSizeBytes = ((header.getBitCount() * width + 31) / 32) * 4;

        // Wrap input according to compression
        imageInput.seek(pixelOffset);
        DataInput input;

        switch (header.getCompression()) {
            case DIB.COMPRESSION_RLE4:
                if (header.getBitCount() != 4) {
                    throw new IIOException(String.format("Unsupported combination of bitCount/compression: %s/%s", header.getBitCount(), header.getCompression()));
                }

                input = new LittleEndianDataInputStream(new DecoderStream(IIOUtil.createStreamAdapter(imageInput), new RLE4Decoder(width), rowSizeBytes));
                break;

            case DIB.COMPRESSION_RLE8:
                if (header.getBitCount() != 8) {
                    throw new IIOException(String.format("Unsupported combination of bitCount/compression: %s/%s", header.getBitCount(), header.getCompression()));
                }
                input = new LittleEndianDataInputStream(new DecoderStream(IIOUtil.createStreamAdapter(imageInput), new RLE8Decoder(width), rowSizeBytes));
                break;

            case DIB.COMPRESSION_BITFIELDS:
            case DIB.COMPRESSION_ALPHA_BITFIELDS:
                // TODO: Validate bitCount for these
            case DIB.COMPRESSION_RGB:
                input = imageInput;
                break;

            default:
                throw new IIOException("Unsupported compression: " + header.getCompression());

        }

        Rectangle srcRegion = new Rectangle();
        Rectangle destRegion = new Rectangle();
        computeRegions(param, width, height, destination, srcRegion, destRegion);

        WritableRaster destRaster = clipToRect(destination.getRaster(), destRegion, param != null ? param.getDestinationBands() : null);
        checkReadParamBandSettings(param, rawType.getNumBands(), destRaster.getNumBands());

        WritableRaster rowRaster;

        switch (header.getBitCount()) {
            case 1:
            case 2:
            case 4:
                rowRaster = Raster.createPackedRaster(new DataBufferByte(rowSizeBytes), width, 1, header.getBitCount(), null);
                break;
            case 8:
            case 24:
                rowRaster = Raster.createInterleavedRaster(new DataBufferByte(rowSizeBytes), width, 1, rowSizeBytes, header.getBitCount() / 8, createOffsets(rawType.getNumBands()), null);
                break;
            case 16:
            case 32:
                rowRaster = rawType.createBufferedImage(width, 1).getRaster();
                break;
            default:
                throw new IIOException("Unsupported pixel depth: " + header.getBitCount());
        }

        // Clip to source region
        Raster clippedRow = clipRowToRect(rowRaster, srcRegion,
                param != null ? param.getSourceBands() : null,
                param != null ? param.getSourceXSubsampling() : 1);

        int xSub = param != null ? param.getSourceXSubsampling() : 1;
        int ySub = param != null ? param.getSourceYSubsampling() : 1;

        processImageStarted(imageIndex);
        for (int y = 0; y < height; y++) {
            int bitCount = header.getBitCount();
            switch (bitCount) {
                case 1:
                case 2:
                case 4:
                case 8:
                case 24:
                    byte[] rowDataByte = ((DataBufferByte) rowRaster.getDataBuffer()).getData();
                    int bitsPerSample = bitCount == 24 ? 8 : bitCount;
                    int samplesPerPixel = bitCount == 24 ? 3 : 1;

                    readRowByte(input, height, srcRegion, xSub, ySub, bitsPerSample, samplesPerPixel, rowDataByte, destRaster, clippedRow, y);
                    break;

                case 16:
                    short[] rowDataUShort = ((DataBufferUShort) rowRaster.getDataBuffer()).getData();
                    readRowUShort(input, height, srcRegion, xSub, ySub, rowDataUShort, destRaster, clippedRow, y);
                    break;

                case 32:
                    int[] rowDataInt = ((DataBufferInt) rowRaster.getDataBuffer()).getData();
                    readRowInt(input, height, srcRegion, xSub, ySub, rowDataInt, destRaster, clippedRow, y);
                    break;

                default:
                    throw new AssertionError("Unsupported pixel depth: " + bitCount);
            }

            processImageProgress(100f * y / height);

            if (height - 1 - y < srcRegion.y) {
                break;
            }

            if (abortRequested()) {
                processReadAborted();
                break;
            }
        }

        processImageComplete();

        return destination;
    }

int[][] decode() throws IOException {
        int current, scanNum = 0;

        xLoc = 0;
        yLoc = 0;
        current = input.readUnsignedShort();

        if (current != JPEG.SOI) { // SOI
            throw new IIOException("Not a JPEG file, does not start with 0xFFD8");
        }

        for (HuffmanTable huffTable : huffTables) {
            huffTable.buildHuffTables(HuffTab);
        }

        quantTable.enhanceTables();

        current = input.readUnsignedShort();

        do {
            // Skip until first SOS
            while (current != JPEG.SOS) {
                input.skipBytes(input.readUnsignedShort() - 2);
                current = input.readUnsignedShort();
            }

            int precision = frame.samplePrecision;

            if (precision == 8) {
                mask = 0xFF;
            }
            else {
                mask = 0xFFFF;
            }

            Frame.Component[] components = frame.components;

            scan = readScan();
            numComp = scan.components.length;
            selection = scan.spectralSelStart;

            final Scan.Component[] scanComps = scan.components;

            for (int i = 0; i < numComp; i++) {
                Frame.Component component = getComponentSpec(components, scanComps[i].scanCompSel);
                qTab[i] = quantTable.qTable(component.qtSel);
                nBlock[i] = component.vSub * component.hSub;

                int dcTabSel = scanComps[i].dcTabSel;
                int acTabSel = scanComps[i].acTabSel;

                // NOTE: If we don't find any DC tables for lossless operation, this file isn't any good.
                // However, we have seen files with AC tables only, we'll treat these as if the AC was DC
                if (useACForDC(dcTabSel)) {
                    processWarningOccured("Lossless JPEG with no DC tables encountered. Assuming only tables present to be DC tables.");

                    dcTab[i] = HuffTab[dcTabSel][1];
                    acTab[i] = HuffTab[acTabSel][0];
                }
                else {
                    // All good
                    dcTab[i] = HuffTab[dcTabSel][0];
                    acTab[i] = HuffTab[acTabSel][1];
                }
            }

            xDim = frame.samplesPerLine;
            yDim = frame.lines;

            outputData = new int[numComp][];

            for (int componentIndex = 0; componentIndex < numComp; ++componentIndex) {
                // not a good use of memory, but I had trouble packing bytes into int.  some values exceeded 255.
                outputData[componentIndex] = new int[xDim * yDim];
            }

            final int[] firstValue = new int[numComp];
            for (int i = 0; i < numComp; i++) {
            	// scan.approxLow is the point transformation (Pt) value
            	// ref. ISO/IEC 10918-1 H.1.2.1
                firstValue[i] = (1 << (precision - scan.approxLow - 1));
            }

            final int[] pred = new int[numComp];

            scanNum++;

            while (true) { // Decode one scan
                int[] temp = new int[1]; // to store remainder bits
                int[] index = new int[1];

                System.arraycopy(firstValue, 0, pred, 0, numComp);

                if (restartInterval == 0) {
                    current = decode(pred, temp, index);

                    while ((current == 0) && ((xLoc < xDim) && (yLoc < yDim))) {
                        output(pred);
                        current = decode(pred, temp, index);
                    }

                    if ((current == JPEG.EOI) && (xLoc == xDim - 1) && (yLoc == yDim - 1)) {
                    	// Output value left in pred if EOI is hit while decoding last pixel
                    	output(pred);
                    }

                    break; //current=MARKER
                }

                for (int mcuNum = 0; mcuNum < restartInterval; mcuNum++) {
                    restarting = (mcuNum == 0);
                    current = decode(pred, temp, index);
                    output(pred);

                    if (current != 0) {
                        break;
                    }
                }

                if (current == 0) {
                    if (markerIndex != 0) {
                        current = (0xFF00 | marker);
                        markerIndex = 0;
                    }
                    else {
                        current = input.readUnsignedShort();
                    }
                }

                if ((current < RESTART_MARKER_BEGIN) || (current > RESTART_MARKER_END)) {
                    break; //current=MARKER
                }
            }

            if ((current == JPEG.DNL) && (scanNum == 1)) { //DNL
                readNumber();
                current = input.readUnsignedShort();
            }
        // TODO oe: 05.05.2018 Is it correct loop? Content of outputData from previous iteration is always lost.
        } while ((current != JPEG.EOI) && ((xLoc < xDim) && (yLoc < yDim)) && (scanNum == 0));

        // Apply point transform to output. This must be done after it has finished being
        // used for predictive purposes.
        if (scan.approxLow != 0) {
        	for (int componentIndex = 0; componentIndex < numComp; ++componentIndex) {
        		int[] comp = outputData[componentIndex];
        		for (int i = 0; i < comp.length; i++) {
        			comp[i] = mask & (comp[i] << scan.approxLow);
        		}
        	}
        }

        return outputData;
    }

