static void loopFilterUVBlock(final MacroBlock cmb, final MacroBlock lmb, final MacroBlock tmb, final int sharpnessLevel, final int frameType) {
        int loop_filter_level = cmb.getFilterLevel();
        if (loop_filter_level != 0) {
            int interior_limit = cmb.getFilterLevel();
            if (sharpnessLevel > 0) {
                interior_limit >>= sharpnessLevel > 4 ? 2 : 1;
                if (interior_limit > 9 - sharpnessLevel) {
                    interior_limit = 9 - sharpnessLevel;
                }
            }
            if (interior_limit == 0) {
                interior_limit = 1;
            }

            int hev_threshold = 0;
            if (frameType == 0) { // current frame is a key frame
                if (loop_filter_level >= 40) {
                    hev_threshold = 2;
                }
                else if (loop_filter_level >= 15) {
                    hev_threshold = 1;
                }
            }
            else  { // current frame is an interframe
                if (loop_filter_level >= 40) {
                    hev_threshold = 3;
                }
                else if (loop_filter_level >= 20) {
                    hev_threshold = 2;
                }
                else if (loop_filter_level >= 15) {
                    hev_threshold = 1;
                }
            }

            // Luma and Chroma use the same inter-macroblock edge limit
            int mbedge_limit = ((loop_filter_level + 2) * 2) + interior_limit;
            // Luma and Chroma use the same inter-subblock edge limit
            int sub_bedge_limit = (loop_filter_level * 2) + interior_limit;

            if (lmb != null) {
                for (int b = 0; b < 2; b++) {
                    SubBlock rsbU = cmb.getSubBlock(SubBlock.Plane.U, 0, b);
                    SubBlock lsbU = lmb.getSubBlock(SubBlock.Plane.U, 1, b);
                    SubBlock rsbV = cmb.getSubBlock(SubBlock.Plane.V, 0, b);
                    SubBlock lsbV = lmb.getSubBlock(SubBlock.Plane.V, 1, b);
                    for (int a = 0; a < 4; a++) {
                        Segment seg = getSegH(rsbU, lsbU, a);
                        MBfilter(hev_threshold, interior_limit, mbedge_limit, seg);
                        setSegH(rsbU, lsbU, seg, a);
                        seg = getSegH(rsbV, lsbV, a);
                        MBfilter(hev_threshold, interior_limit, mbedge_limit, seg);
                        setSegH(rsbV, lsbV, seg, a);
                    }
                }
            }
            // sb left

            if (!cmb.isSkip_inner_lf()) {
                for (int a = 1; a < 2; a++) { // TODO: This does not loop?
                    for (int b = 0; b < 2; b++) {
                        SubBlock lsbU = cmb.getSubBlock(SubBlock.Plane.U, a - 1, b);
                        SubBlock rsbU = cmb.getSubBlock(SubBlock.Plane.U, a, b);
                        SubBlock lsbV = cmb.getSubBlock(SubBlock.Plane.V, a - 1, b);
                        SubBlock rsbV = cmb.getSubBlock(SubBlock.Plane.V, a, b);
                        for (int c = 0; c < 4; c++) {
                            Segment seg = getSegH(rsbU, lsbU, c);
                            subblock_filter(hev_threshold, interior_limit, sub_bedge_limit, seg);
                            setSegH(rsbU, lsbU, seg, c);
                            seg = getSegH(rsbV, lsbV, c);
                            subblock_filter(hev_threshold, interior_limit, sub_bedge_limit, seg);
                            setSegH(rsbV, lsbV, seg, c);
                        }
                    }
                }
            }

            // top
            if (tmb != null) {
                for (int b = 0; b < 2; b++) {
                    SubBlock tsbU = tmb.getSubBlock(SubBlock.Plane.U, b, 1);
                    SubBlock bsbU = cmb.getSubBlock(SubBlock.Plane.U, b, 0);
                    SubBlock tsbV = tmb.getSubBlock(SubBlock.Plane.V, b, 1);
                    SubBlock bsbV = cmb.getSubBlock(SubBlock.Plane.V, b, 0);
                    for (int a = 0; a < 4; a++) {
                        // System.out.println("l");
                        Segment seg = getSegV(bsbU, tsbU, a);
                        MBfilter(hev_threshold, interior_limit, mbedge_limit, seg);
                        setSegV(bsbU, tsbU, seg, a);
                        seg = getSegV(bsbV, tsbV, a);
                        MBfilter(hev_threshold, interior_limit, mbedge_limit, seg);
                        setSegV(bsbV, tsbV, seg, a);
                    }
                }
            }

            // sb top
            if (!cmb.isSkip_inner_lf()) {
                for (int a = 1; a < 2; a++) { // TODO: This does not loop...
                    for (int b = 0; b < 2; b++) {
                        SubBlock tsbU = cmb.getSubBlock(SubBlock.Plane.U, b, a - 1);
                        SubBlock bsbU = cmb.getSubBlock(SubBlock.Plane.U, b, a);
                        SubBlock tsbV = cmb.getSubBlock(SubBlock.Plane.V, b, a - 1);
                        SubBlock bsbV = cmb.getSubBlock(SubBlock.Plane.V, b, a);
                        for (int c = 0; c < 4; c++) {
                            Segment seg = getSegV(bsbU, tsbU, c);
                            subblock_filter(hev_threshold, interior_limit, sub_bedge_limit, seg);
                            setSegV(bsbU, tsbU, seg, c);
                            seg = getSegV(bsbV, tsbV, c);
                            subblock_filter(hev_threshold, interior_limit, sub_bedge_limit, seg);
                            setSegV(bsbV, tsbV, seg, c);
                        }
                    }
                }
            }
        }
    }

public void predictUV(VP8Frame frame) {
        MacroBlock aboveMb = frame.getMacroBlock(x, y - 1);
        MacroBlock leftMb = frame.getMacroBlock(x - 1, y);

        switch (this.uvMode) {
            case Globals.DC_PRED:
                // System.out.println("UV DC_PRED");

                boolean up_available = false;
                boolean left_available = false;
                int Uaverage = 0;
                int Vaverage = 0;
                int expected_udc;
                int expected_vdc;
                if (x > 0) {
                    left_available = true;
                }
                if (y > 0) {
                    up_available = true;
                }
                if (up_available || left_available) {
                    if (up_available) {
                        for (int j = 0; j < 2; j++) {
                            SubBlock usb = aboveMb.getUSubBlock(j, 1);
                            SubBlock vsb = aboveMb.getVSubBlock(j, 1);
                            for (int i = 0; i < 4; i++) {
                                Uaverage += usb.getRecon()[i][3];
                                Vaverage += vsb.getRecon()[i][3];
                            }
                        }
                    }

                    if (left_available) {
                        for (int j = 0; j < 2; j++) {
                            SubBlock usb = leftMb.getUSubBlock(1, j);
                            SubBlock vsb = leftMb.getVSubBlock(1, j);
                            for (int i = 0; i < 4; i++) {
                                Uaverage += usb.getRecon()[3][i];
                                Vaverage += vsb.getRecon()[3][i];
                            }
                        }
                    }

                    int shift = 2;
                    if (up_available) {
                        shift++;
                    }
                    if (left_available) {
                        shift++;
                    }

                    expected_udc = (Uaverage + (1 << (shift - 1))) >> shift;
                    expected_vdc = (Vaverage + (1 << (shift - 1))) >> shift;
                }
                else {
                    expected_udc = 128;
                    expected_vdc = 128;
                }

                int[][] ufill = new int[4][4];
                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        ufill[x][y] = expected_udc;
                    }
                }

                int[][] vfill = new int[4][4];
                for (int y = 0; y < 4; y++) {
                    for (int x = 0; x < 4; x++) {
                        vfill[x][y] = expected_vdc;
                    }
                }

                for (int y = 0; y < 2; y++) {
                    for (int x = 0; x < 2; x++) {
                        SubBlock usb = uSubBlocks[x][y];
                        SubBlock vsb = vSubBlocks[x][y];
                        usb.setPredict(ufill);
                        vsb.setPredict(vfill);
                    }
                }

                break;
            case Globals.V_PRED:
                // System.out.println("UV V_PRED");

                SubBlock[] aboveUSb = new SubBlock[2];
                SubBlock[] aboveVSb = new SubBlock[2];
                for (int x = 0; x < 2; x++) {
                    aboveUSb[x] = aboveMb.getUSubBlock(x, 1);
                    aboveVSb[x] = aboveMb.getVSubBlock(x, 1);
                }

                for (int y = 0; y < 2; y++) {
                    for (int x = 0; x < 2; x++) {
                        SubBlock usb = uSubBlocks[y][x];
                        SubBlock vsb = vSubBlocks[y][x];
                        int[][] ublock = new int[4][4];
                        int[][] vblock = new int[4][4];
                        for (int j = 0; j < 4; j++) {
                            for (int i = 0; i < 4; i++) {
                                ublock[j][i] = aboveUSb[y]
                                        .getMacroBlockReconPredict(Globals.V_PRED)[j][3];
                                vblock[j][i] = aboveVSb[y]
                                        .getMacroBlockReconPredict(Globals.V_PRED)[j][3];
                            }
                        }
                        usb.setPredict(ublock);
                        vsb.setPredict(vblock);
                    }
                }

                break;

            case Globals.H_PRED:
                // System.out.println("UV H_PRED");

                SubBlock[] leftUSb = new SubBlock[2];
                SubBlock[] leftVSb = new SubBlock[2];
                for (int x = 0; x < 2; x++) {
                    leftUSb[x] = leftMb.getUSubBlock(1, x);
                    leftVSb[x] = leftMb.getVSubBlock(1, x);
                }

                for (int y = 0; y < 2; y++) {
                    for (int x = 0; x < 2; x++) {
                        SubBlock usb = uSubBlocks[x][y];
                        SubBlock vsb = vSubBlocks[x][y];
                        int[][] ublock = new int[4][4];
                        int[][] vblock = new int[4][4];
                        for (int j = 0; j < 4; j++) {
                            for (int i = 0; i < 4; i++) {
                                ublock[i][j] = leftUSb[y]
                                        .getMacroBlockReconPredict(Globals.H_PRED)[3][j];
                                vblock[i][j] = leftVSb[y]
                                        .getMacroBlockReconPredict(Globals.H_PRED)[3][j];
                            }
                        }
                        usb.setPredict(ublock);
                        vsb.setPredict(vblock);
                    }
                }

                break;
            case Globals.TM_PRED:
                // TODO:
                // System.out.println("UV TM_PRED MB");
                boolean aboveRowAvailableUV = this.y > 0;
                MacroBlock ALMb = frame.getMacroBlock(x - 1, y - 1);
                SubBlock ALUSb = ALMb.getUSubBlock(1, 1);
                int alu = ALUSb.getReconAboveLeft(aboveRowAvailableUV)[3][3];
                SubBlock ALVSb = ALMb.getVSubBlock(1, 1);
                int alv = ALVSb.getReconAboveLeft(aboveRowAvailableUV)[3][3];

                aboveUSb = new SubBlock[2];
                leftUSb = new SubBlock[2];
                aboveVSb = new SubBlock[2];
                leftVSb = new SubBlock[2];
                for (int x = 0; x < 2; x++) {
                    aboveUSb[x] = aboveMb.getUSubBlock(x, 1);
                    leftUSb[x] = leftMb.getUSubBlock(1, x);
                    aboveVSb[x] = aboveMb.getVSubBlock(x, 1);
                    leftVSb[x] = leftMb.getVSubBlock(1, x);
                }

                for (int b = 0; b < 2; b++) {
                    for (int a = 0; a < 4; a++) {
                        for (int d = 0; d < 2; d++) {
                            for (int c = 0; c < 4; c++) {

                                int upred = leftUSb[b].getReconLeft()[3][a]
                                        + aboveUSb[d].getReconAbove()[c][3] - alu;
                                upred = Globals.clamp(upred, 255);
                                uSubBlocks[d][b].setPixel(c, a, upred);

                                int vpred = leftVSb[b].getReconLeft()[3][a]
                                        + aboveVSb[d].getReconAbove()[c][3] - alv;
                                vpred = Globals.clamp(vpred, 255);
                                vSubBlocks[d][b].setPixel(c, a, vpred);
                            }
                        }
                    }
                }

                break;
            default:
                // TODO: FixME!
                throw new AssertionError("TODO predict_mb_uv: " + this.yMode);
        }
    }

